mapper.select:
with claim_record_group as ( select ebank_serial_number , sum(claim_amount) claim_amount , max(business_date) business_happen_date from eg_business_claim_repayment_record where del_flag = '0' and process_status in ('3', '4') group by ebank_serial_number ) select ccs.collection_accounts_bank , cr.org_id , cr.org_name , ccs.business_ebank_number , cr.ebank_serial_number , cr.system_code , crg.business_happen_date last_change_date , ccs.business_date ebank_income_date, ccs.currency_type , coalesce(ccs.bank_amount, 0) as bank_amount, coalesce(ccs.bank_amount, 0) - coalesce(crg.claim_amount) as remain_amount, coalesce(cr.claim_amount, 0) as claim_amount, cr.business_date ebank_confirm_date , cr.contract_code, cr.operation_type , case when cr.operation_type = 'BUSINESS_AUTO_CLAIM' then '是' when cr.operation_type != 'BUSINESS_AUTO_CLAIM' then '否' end as is_relation_business, ccs.collection_accounts_bank_no, ccs.collection_accounts_bank, ccs.client_code, ccs.client_name, ccs.bank_summary, ccs.comment, ccs.client_accounts_bank_no, case when cr.operation_type = 'MODIFY_EBANK_NO' then to_char(cr.business_date, 'yyyy-MM-dd') || ' ' || cr.new_ebank_serial_number || ' ' || cr.claim_amount when cr.operation_type != 'MODIFY_EBANK_NO' then '' end as adjustment_record, cr.remark from eg_business_claim_repayment_record cr left join eg_non_confirm_collection_sum ccs on ccs.ebank_serial_number = cr.ebank_serial_number and ccs.del_flag ='0' left join claim_record_group crg on cr.ebank_serial_number = crg.ebank_serial_number where cr.del_flag = '0'
and ccs.business_ebank_number like concat('%', #{params.businessEbankNumber}, '%')
and cr.ebank_serial_number like concat('%', #{params.ebankSerialNumber}, '%')
and ccs.collection_accounts_bank_no like concat('%', #{params.collectionAccountsBankNo}, '%')
and cr.business_date >= #{params.businessDateStart}
and cr.business_date <= #{params.businessDateEnd}
and ccs.client_name like concat('%', #{params.clientName}, '%')
and crg.business_happen_date >= #{params.lastChangeDateStart}
and crg.business_happen_date <= #{params.lastChangeDateEnd}
and ccs.bank_amount != crg.claim_amount
and ccs.bank_amount = crg.claim_amount
order by ccs.business_ebank_number , cr.ebank_serial_number , crg.business_happen_date desc, ccs.business_date desc
